        products = [flat[i] for i in sorted(flat)]
    p = products[0] if products else None
    if not isinstance(p, dict) or p.get('past_due') in (None, ''):
        raise ValueError('no product')
    def num(x):
        try:
            return float(x)
        except Exception:
            return None
    def money(x):
        if x is None:
            return 'unknown'
