            return str(int(round(x)))
        return '%.2f' % x
    ptype = str(p.get('type') or '')
    if ptype == 'credit_card':
        last4 = str(p.get('card_last4') or '').strip()
        phrase = 'credit card ending ' + last4 if last4 else 'credit card'
