        y = x + datetime.timedelta(days=7)
        this_w.append('"this ' + WD[i] + '" = ' + x.isoformat() + ('' if x >= today else ' (already past)'))
        next_w.append('"next ' + WD[i] + '" = ' + y.isoformat())
