# ------------------------------------------------------------------ tools

def verify_tool():
    return api_tool(
        "verify_identity",
        "Check one security answer. CALL it every time the customer gives an answer to a security question, once per answer.",
        {
            "customer_id": leaf("string", "{{customer_id}}"),
