def callback_tool():
    return api_tool(
        "schedule_callback",
        "Book a callback. CALL it when the person names a day and a time that are inside the allowed callback window.",
        {
            "customer_id": leaf("string", "{{customer_id}}"),
            "date": leaf("string", "{{callback_date}}", "Callback date as YYYY-MM-DD."),
